function renderPrompt(){
  const box=$('#promptResults'), cnt=$('#promptCount'); if(!box) return;
  if(csaState.promptSel!=null && CSA_PROMPT[csaState.promptSel]){
    box.innerHTML=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="promptBack">&larr; Back to guides</button></div>${promptDetail(CSA_PROMPT[csaState.promptSel])}`;
    const bk=$('#promptBack'); if(bk) bk.onclick=()=>{ csaState.promptSel=null; renderPrompt(); const r=$('#promptResults'); if(r) r.scrollIntoView({behavior:'smooth',block:'nearest'}); };
    if(cnt) cnt.textContent=''; bindCopy(); return;
  }
  const q=(csaState.promptQ||'').trim().toLowerCase();
  const toks=q.split(/[^a-z0-9]+/).filter(t=>t.length>1);
  let list=CSA_PROMPT.map((e,i)=>({e,i})).filter(({e})=>(csaState.promptCat==='all'||e.cat===csaState.promptCat));
  if(toks.length){ list=list.filter(({e})=>{ const hay=(e.title+' '+e.summary+' '+(e.points||[]).join(' ')+' '+(e.script||'')+' '+(e.bad||'')+' '+(e.good||'')).toLowerCase(); return toks.every(t=>hay.includes(t)); }); }
  if(cnt) cnt.textContent=`${list.length} guide${list.length===1?'':'s'}`;
  if(!list.length){ box.innerHTML=`<div class="csaResHint">No matches &mdash; try <b>template</b>, <b>batching</b>, <b>output format</b>, or <b>reuse context</b>.</div>`; return; }
  box.innerHTML=`<div class="kbGrid">${list.map(({e,i})=>promptCard(e,i)).join('')}</div>`;
  box.querySelectorAll('.promptOpen').forEach(b=>b.onclick=()=>{ csaState.promptSel=+b.dataset.i; renderPrompt(); const r=$('#promptResults'); if(r) r.scrollIntoView({behavior:'smooth',block:'nearest'}); });
}
