  if(q){ const match=DATA.workflows.find(w=>(w.name+' '+w.desc+' '+w.dept+' '+w.currentTools+' '+w.recommendedTools+' '+w.repetitive.join(' ')+' '+(w.keywords||[]).join(' ')).toLowerCase().includes(q)); if(match) state.activeId=match.id; }
